section Section1;
shared p_schoolowners_s = let AdfDoc = AzureStorage.DataLakeContents("https://growecdstorage.dfs.core.windows.net/giraffe/parque/p_schoolowners_s.parquet"), Parquet = Parquet.Document(AdfDoc) in Parquet;
shared UserQuery = let  
    Source = #"p_schoolowners_s",  

    #"Added custom" = Table.TransformColumnTypes(  
        Table.AddColumn(Source, "personimport", each true),  
        {{"personimport", type logical}}  
    ),  

    #"Added custom 1" = Table.TransformColumnTypes(  
        Table.AddColumn(#"Added custom", "personimportdone", each false),  
        {{"personimportdone", type logical}}  
    ),  

    #"Replaced value" = Table.ReplaceValue(#"Added custom 1", "Male", "1", Replacer.ReplaceText, {"gender"}),  
    #"Replaced value 1" = Table.ReplaceValue(#"Replaced value", "Female", "2", Replacer.ReplaceText, {"gender"}),  
    #"Replaced value 2" = Table.ReplaceValue(#"Replaced value 1", "NULL", "3", Replacer.ReplaceText, {"gender"}),  

    #"Added custom 2" = Table.TransformColumnTypes(  
        Table.AddColumn(#"Replaced value 2", "DateUpdated", each DateTime.Date(DateTime.LocalNow())),  
        {{"DateUpdated", type date}}  
    ),  

    #"Added custom 3" = Table.TransformColumnTypes(  
        Table.AddColumn(#"Added custom 2", "FullName", each [first_name] & " " & [last_name]),  
        {{"FullName", type text}}  
    ),  

// ✅ CLEAN ADDRESS COLUMN (Spark Runtime Compatible)  
CleanText = (txt as nullable text) =>  
    if txt = null then null else  
    Text.Remove(  
        txt,  
        List.Transform({0..31}, each Character.FromNumber(_))  
    ),  

#"Cleaned address" = Table.TransformColumns(  
    #"Added custom 3",  
    {{"address", CleanText, type text}}  
),    

    #"Replaced value 4" = Table.ReplaceValue(#"Cleaned address", ":", "", Replacer.ReplaceText, {"address"}),  
    #"Replaced value 5" = Table.ReplaceValue(#"Replaced value 4", """", "", Replacer.ReplaceText, {"address"}),  

    #"Changed column type" = Table.TransformColumnTypes(#"Replaced value 5", {{"gender", Int64.Type}}),  

    #"Removed other columns" = Table.SelectColumns(  
        #"Changed column type",  
        {"id", "address", "alternative_number", "city_id", "updated_at", "contact_no", "country_of_birth_id", "date_of_birth", "email", "first_name", "last_name", "FullName", "preferred_name", "race_type_id", "region_id"}  
    ),  

    #"Renamed columns" = Table.RenameColumns(  
        #"Removed other columns",  
        {  
            {"address", "tcbgrow_address"},  
            {"alternative_number", "tcbgrow_alternativenumber"},  
            {"id", "tcbgrow_appid"},  
            {"city_id", "tcbgrow_city"},  
            {"contact_no", "tcbgrow_contactnumber"},  
            {"country_of_birth_id", "tcbgrow_countryofbirth"},  
            {"date_of_birth", "tcbgrow_dateofbirth"},  
            {"email", "tcbgrow_emailaddress"},  
            {"first_name", "tcbgrow_firstname"},  
            {"last_name", "tcbgrow_lastname"},  
            {"FullName", "tcbgrow_name"},  
            {"preferred_name", "tcbgrow_preferredname"},  
            {"race_type_id", "tcbgrow_race"},  
            {"region_id", "cog_region"},  
            {"updated_at", "tcbgrow_lastappdate"}  
        }  
    )  

in  
    #"Renamed columns";
